def practice9(r,f):
    r.start(9,'исследовать поведение системы подготовки карточек, описать взаимодействие объектов и построить UML-диаграммы деятельности и последовательности.')
    r.h('Этапы выполнения работы');r.p('Выбран сквозной сценарий отправки утверждённой карточки и получения результата, объединяющий UC-07 и UC-08. Определены участвующие объекты, сообщения, состояния и альтернативные исходы. Построена диаграмма последовательности и подготовлена табличная спецификация деятельности; для проверки рассмотрены успех, отклонение и потеря ответа.')
    r.table('Словарь модели взаимодействия',['Термин / объект','Назначение'],[
    ['менеджер','Актор, подтверждающий передачу выбранной карточки.'],['ui : Интерфейс','Граничный объект, принимает команду и показывает попытку и статус.'],['svc : Публикация','Управляющий объект; проверяет допустимость операции и вызывает адаптер.'],['repo : Репозиторий','Сохраняет пакет, версию, попытку и события в согласованном состоянии.'],['ozon : Ozon','Представление внешней системы в модели; обрабатывает пакет вне локальной транзакции.'],['attemptId','Внутренний идентификатор одной попытки, существующий до внешней отправки.'],['Идентификатор обработки','Ссылка внешней системы, используемая для сопоставления ответа, когда она предоставлена.'],['Возвращающее сообщение','Ответ вызывающей стороне с результатом локальной операции или внешнего запроса.'],
    ],[4.5,11])
    r.h('Логика взаимодействия объектов')
    r.p('Интерфейс передаёт идентификатор карточки и ожидаемую версию сервису публикации. Сервис проверяет права, актуальность версии и обязательные реквизиты. Репозиторий сохраняет попытку до внешнего вызова, поэтому сетевой сбой не уничтожает сведения об операции. Команда менеджера завершается после регистрации отправки; получение окончательного результата выполняется отдельно.')
    r.p('Локальная транзакция не распространяется на Ozon. Поэтому нельзя считать её откат гарантией отмены внешней публикации. При тайм-ауте система сохраняет неопределённый результат и сначала пытается сопоставить уже созданную операцию. Правила повторов зависят от подтверждённых возможностей внешнего интерфейса: отсутствие ответа не является основанием для безусловной повторной отправки.')
    r.orient(True);r.h('Диаграмма последовательности');r.fig(f['sequence'],'Взаимодействие при передаче карточки и запросе результата')
    r.orient(False)
    r.p('На рисунке 9.1 показана основная последовательность. Сообщения 1–8 относятся к регистрации и передаче, 9–10 — к отдельной последующей проверке. Пунктирные горизонтальные стрелки обозначают возвраты. Временной промежуток между сообщениями 8 и 9 не фиксирован и определяется регламентом опроса. После сообщения 10 сервис сохраняет результат через репозиторий и обновляет доступный пользователю статус. Объекты не уничтожаются в ходе взаимодействия.')
    r.table('Словарь модели деятельности',['Элемент','Смысл в рассматриваемом процессе'],[
    ['Дорожка','Ответственность менеджера, информационной системы или Ozon.'],['Действие','Завершённая операция: проверка, сохранение, передача или получение результата.'],['Решение','Проверка готовности карточки либо наличия подтверждённого ответа.'],['Сторожевое условие','Взаимоисключающие условия [да] и [нет] для каждой проверки.'],['Попытка в ожидании','Сохранённая операция, окончательный исход которой ещё не подтверждён.'],['Конечный узел','Завершение текущего сценария; новый запуск после исправлений является отдельной операцией.'],
    ],[4.5,11])
    r.table('Действия, переходы и ответственность',['Действие','Следующий шаг / условие','Дорожка','Объект'],[
    ['Выбрать и подтвердить карточку','Проверить допуск','Менеджер','Карточка'],['Проверить поля и версии','[да] — сохранить; [нет] — исправить','ИС','Карточка, BOM'],['Исправить замечания','Завершить текущий сценарий; повторить после подготовки','Менеджер','Черновик'],['Сохранить попытку','Передать пакет','ИС','Попытка, пакет'],['Принять и обработать','Вернуть идентификатор / результат','Ozon','Внешняя операция'],['Получить статус','[ответ есть] — сохранить итог; [нет] — ожидание','ИС','Ответ'],['Сохранить ожидание','Позже запросить статус той же операции','ИС','Попытка'],['Сохранить итог','Завершить; отклонённую карточку можно доработать','ИС','Статус, замечания'],
    ],[4.5,5.2,2.8,3.0])
    r.h('Контрольные сценарии модели')
    r.p('Успех: утверждённый пакет проходит проверку, сохраняется и передаётся; после подтверждённого ответа карточка получает статус «опубликовано». Ошибка реквизитов: отправка не выполняется, менеджер получает перечень замечаний. Отклонение внешней системой: исходный ответ сохраняется, карточка возвращается на доработку с историей попытки. Потеря ответа: операция остаётся в ожидании, а запросы статуса не создают новые публикации.')
    r.p('Ветви решения «карточка готова?» завершаются либо отдельным конечным узлом возврата на доработку, либо продолжением отправки. Ветви решения «ответ получен?» ведут к итоговому состоянию или возврату в цикл проверки. Параллельных потоков в данной модели нет; скрытого одновременного исполнения действий она не предполагает.')
    r.h('Выводы');r.p('Динамическая модель отделяет локальное сохранение от внешней обработки и делает неопределённый исход наблюдаемым состоянием. Диаграмма последовательности и табличное описание деятельности конкретизируют порядок сообщений, ответственность участников и обработку ошибок, необходимые для реализации F-08–F-10 и R-01–R-03.')

